// M26-B.1  Periodic Hann window (sample-wise multiply).
//
//   y[n] = x[n] * w[n],  w[n] = 0.5 - 0.5*cos(2*pi*n/1024),  n = 0..1023
//
// Per M26_FIXED_POINT_CONTRACT.md §7: the window coefficient is a 16-bit Q1.15 ROM
// (`m26_hann.mem`, generated by scripts/gen_m26_roms.py from m26golden::hann_window),
// indexed by the sample position within the frame (a 10-bit counter reset by tlast).
// The product x[n]*w[n] is Q2.30, rounded (round-half-away-from-zero) and symmetrically
// saturated to Q1.15.  bypass=1 -> passthrough (1-cycle latency, order unchanged).
module m26_hann (
    input  logic        clk,
    input  logic        rst_n,          // async, active-low
    input  logic        bypass,
    input  logic        s_axis_tvalid,
    output logic        s_axis_tready,
    input  logic [31:0] s_axis_tdata,   // {I[15:0], Q[15:0]}
    input  logic        s_axis_tlast,
    output logic        m_axis_tvalid,
    input  logic        m_axis_tready,
    output logic [31:0] m_axis_tdata,
    output logic        m_axis_tlast
);
  import m26_fxp_pkg::*;

  logic signed [15:0] w [0:1023];
  initial $readmemh("m26_hann.mem", w);

  logic [9:0]  cnt;                     // sample position in frame (0..1023)
  logic        out_valid;

  wire signed [15:0] x_re = $signed(s_axis_tdata[15:0]);
  wire signed [15:0] x_im = $signed(s_axis_tdata[31:16]);
  wire signed [15:0] w_sel = w[cnt];
  wire signed [31:0] p_re = x_re * w_sel;   // Q2.30
  wire signed [31:0] p_im = x_im * w_sel;

  assign s_axis_tready = !out_valid || m_axis_tready;
  assign m_axis_tvalid = out_valid;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      cnt       <= 10'd0;
      out_valid <= 1'b0;
    end else begin
      if (s_axis_tready && s_axis_tvalid) begin
        if (bypass)
          m_axis_tdata <= s_axis_tdata;
        else
          m_axis_tdata <= {rshift_round_sat16(p_im, 15), rshift_round_sat16(p_re, 15)};
        m_axis_tlast <= s_axis_tlast;
        out_valid    <= 1'b1;
        cnt          <= s_axis_tlast ? 10'd0 : cnt + 10'd1;
      end else if (m_axis_tready && out_valid) begin
        out_valid <= 1'b0;
      end
    end
  end

endmodule
